        a->top->used += n;
        /* A block straight from `calloc` is zero **throughout**, and only the bytes not yet
         * handed out are ever looked at again, so those need no clearing; a block that came
         * back from the spare was written to in its previous life and does. The promise is
         * unchanged either way: a byte read after its lifetime ends is an initialized byte
         * (SPEC section 0.6). Skipping it matters for the one-shot large buffer: a 32 MiB
         * `new` pays only for what it touches, since a fresh block is
         * already zero and needs no `memset`. */
        if (!a->top->fresh) memset(p, 0, (size_t)n);
